private val Purple = Color(0xFF6D4AFF); private val PurpleSoft = Color(0xFFF0EBFF); private val Green = Color(0xFF18A86B); private val GreenSoft = Color(0xFFE8F8F0); private val Orange = Color(0xFFF2A20B); private val OrangeSoft = Color(0xFFFFF5DF); private val Page = Color(0xFFF8F9FD)
private const val FILE_LIMIT = 1_000_000
private data class FileFilter(val label: String, val category: BackupCategory?, val icon: androidx.compose.ui.graphics.vector.ImageVector)
private val filters = listOf(FileFilter("All", null, Icons.Default.GridView), FileFilter("Photos", BackupCategory.PHOTOS, Icons.Default.Image), FileFilter("Videos", BackupCategory.VIDEOS, Icons.Default.VideoFile), FileFilter("PDFs", BackupCategory.PDFS, Icons.Default.PictureAsPdf), FileFilter("Docs", BackupCategory.WORD_EXCEL, Icons.Default.Description), FileFilter("Audio", BackupCategory.AUDIO, Icons.Default.AudioFile))

@OptIn(ExperimentalMaterial3Api::class)
@Composable fun FilesHubScreen(nav: NavHostController, initialCategory: BackupCategory? = null) {
    val context = LocalContext.current; val dao = remember { AppDatabase.get(context).fileRecordDao() }
    var category by remember(initialCategory) { mutableStateOf(initialCategory) }; var query by remember { mutableStateOf("") }; var status by remember { mutableStateOf("") }; var sort by remember { mutableStateOf("newest") }; var search by remember { mutableStateOf(false) }; var filtersOpen by remember { mutableStateOf(false) }
    val categoryName = category?.name ?: ""
    val files by remember(query, categoryName, status, sort) { dao.searchFlow(query.trim(), categoryName, status, "", "", 0L, 0L, 0L, 0L, 0L, sort, FILE_LIMIT) }.collectAsState(initial = emptyList())
    val total by remember(query, categoryName, status) { dao.searchCountFlow(query.trim(), categoryName, status, "", "", 0L, 0L, 0L, 0L, 0L) }.collectAsState(initial = 0)
    val uploaded by remember(query, categoryName) { dao.searchCountFlow(query.trim(), categoryName, "UPLOADED", "", "", 0L, 0L, 0L, 0L, 0L) }.collectAsState(initial = 0)
    val pending by remember(query, categoryName) { dao.searchCountFlow(query.trim(), categoryName, "PENDING", "", "", 0L, 0L, 0L, 0L, 0L) }.collectAsState(initial = 0)
    if (filtersOpen) FilesFilterSheet(category, status, sort, { category = it }, { status = it }, { sort = it }, { category = null; status = ""; sort = "newest" }, { filtersOpen = false })
    Scaffold(containerColor = Page) { pad -> Column(Modifier.fillMaxSize().padding(pad)) {
        val title = if (category == null) "Files" else categoryLabel(category!!)
        TopAppBar(title = { Column { Text(title, fontWeight = FontWeight.Bold); Text(if (category == null) "All files in AirDrive" else "${Format.count(total)} files", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant) } }, navigationIcon = { IconButton(onClick = { nav.popBackStack() }) { Icon(Icons.Default.ArrowBack, "Back") } }, actions = { IconButton(onClick = { search = !search }) { Icon(Icons.Default.Search, "Search") }; IconButton(onClick = { filtersOpen = true }) { Icon(Icons.Default.FilterList, "Filters & Sort") } })
        if (search) OutlinedTextField(query, { query = it }, Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 3.dp), singleLine = true, leadingIcon = { Icon(Icons.Default.Search, null) }, placeholder = { Text("Search files, folders, extensions…") }, shape = RoundedCornerShape(17.dp))
        Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()).padding(horizontal = 16.dp, vertical = 8.dp), horizontalArrangement = Arrangement.spacedBy(9.dp)) { filters.forEach { f -> CategoryShortcut(f, category == f.category) { if (f.category == BackupCategory.PHOTOS || f.category == BackupCategory.VIDEOS) nav.navigate("${Routes.GALLERY}/${if (f.category == BackupCategory.PHOTOS) "photos" else "videos"}") else category = f.category } } }
        Row(Modifier.fillMaxWidth().padding(horizontal = 16.dp), horizontalArrangement = Arrangement.spacedBy(10.dp)) { StatusCard("Uploaded", uploaded, Green, GreenSoft, status == "UPLOADED") { status = if (status == "UPLOADED") "" else "UPLOADED" }; StatusCard("Pending", pending, Orange, OrangeSoft, status == "PENDING") { status = if (status == "PENDING") "" else "PENDING" } }
        Row(Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 12.dp), verticalAlignment = Alignment.CenterVertically) { Column(Modifier.weight(1f)) { Text("All files", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold); Text("${Format.count(total)} files", style = MaterialTheme.typography.labelSmall, color = Purple) }; SortPill(sort) { sort = it }; IconButton(onClick = { filtersOpen = true }) { Icon(Icons.Default.FilterList, null, tint = Purple) } }
        if (files.isEmpty()) EmptyFiles() else LazyColumn(Modifier.fillMaxSize(), contentPadding = PaddingValues(horizontal = 16.dp, vertical = 2.dp), verticalArrangement = Arrangement.spacedBy(9.dp)) { items(files, key = { it.id }) { FileRow(it, nav) } }
    } }
}

@Composable private fun CategoryShortcut(f: FileFilter, selected: Boolean, onClick: () -> Unit) { val tint = when (f.category) { BackupCategory.PHOTOS -> Color(0xFF25B5A7); BackupCategory.VIDEOS -> Orange; BackupCategory.PDFS -> Color(0xFFE53935); BackupCategory.WORD_EXCEL -> Color(0xFF3478D4); BackupCategory.AUDIO -> Purple; else -> Purple }; Column(Modifier.width(58.dp).clickable(onClick = onClick), horizontalAlignment = Alignment.CenterHorizontally) { Surface(modifier = Modifier.size(48.dp), shape = RoundedCornerShape(14.dp), color = if (selected) PurpleSoft else Color.White, tonalElevation = 1.dp) { Box(contentAlignment = Alignment.Center) { Icon(f.icon, null, tint = if (selected) Purple else tint, modifier = Modifier.size(23.dp)) } }; Text(f.label, style = MaterialTheme.typography.labelSmall, fontWeight = if (selected) FontWeight.Bold else FontWeight.Normal) } }
@Composable private fun RowScope.StatusCard(title: String, count: Int, accent: Color, soft: Color, selected: Boolean, onClick: () -> Unit) { Card(modifier = Modifier.weight(1f).clickable(onClick = onClick), shape = RoundedCornerShape(17.dp), colors = CardDefaults.cardColors(containerColor = if (selected) soft else Color.White), border = if (selected) BorderStroke(1.dp, accent.copy(alpha = .5f)) else null) { Row(Modifier.padding(11.dp), verticalAlignment = Alignment.CenterVertically) { Icon(if (accent == Green) Icons.Default.CheckCircle else Icons.Default.Schedule, null, tint = accent, modifier = Modifier.size(22.dp)); Spacer(Modifier.width(8.dp)); Column { Text(title, style = MaterialTheme.typography.labelSmall); Text(Format.count(count), fontWeight = FontWeight.Bold, color = accent) } } } }
@Composable private fun SortPill(sort: String, onSort: (String) -> Unit) { var open by remember { mutableStateOf(false) }; Box { Surface(modifier = Modifier.clickable { open = true }, shape = RoundedCornerShape(13.dp), color = Color.White) { Row(Modifier.padding(horizontal = 11.dp, vertical = 9.dp), verticalAlignment = Alignment.CenterVertically) { Icon(Icons.Default.Sort, null, modifier = Modifier.size(16.dp)); Spacer(Modifier.width(5.dp)); Text(sortText(sort), style = MaterialTheme.typography.labelMedium); Text("⌄") } }; DropdownMenu(expanded = open, onDismissRequest = { open = false }) { listOf("newest" to "Newest first", "oldest" to "Oldest first", "largest" to "Largest size", "smallest" to "Smallest size", "name" to "Name (A–Z)").forEach { (v, l) -> DropdownMenuItem(text = { Text(l) }, onClick = { onSort(v); open = false }) } } } }
@Composable private fun FileRow(record: FileRecord, nav: NavHostController) { var menu by remember { mutableStateOf(false) }; val tint = categoryTint(record.category); Card(modifier = Modifier.fillMaxWidth(), shape = RoundedCornerShape(17.dp), colors = CardDefaults.cardColors(containerColor = Color.White)) { Row(Modifier.padding(10.dp), verticalAlignment = Alignment.CenterVertically) { Preview(record, tint); Spacer(Modifier.width(11.dp)); Column(Modifier.weight(1f).clickable { nav.navigate("${Routes.FILE_VIEWER}/${record.id}") }) { Text(record.displayName, maxLines = 1, overflow = TextOverflow.Ellipsis, fontWeight = FontWeight.SemiBold); Text("${Format.bytes(record.sizeBytes)} • ${record.category.name.lowercase(Locale.getDefault()).replace('_', ' ')}", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant); Row(verticalAlignment = Alignment.CenterVertically) { Icon(if (record.status == UploadStatus.UPLOADED) Icons.Default.CheckCircle else Icons.Default.Schedule, null, tint = if (record.status == UploadStatus.UPLOADED) Green else Orange, modifier = Modifier.size(14.dp)); Spacer(Modifier.width(4.dp)); Text(if (record.status == UploadStatus.UPLOADED) "Backed up to Telegram" else "Pending upload", style = MaterialTheme.typography.labelSmall, color = if (record.status == UploadStatus.UPLOADED) Green else Orange) } }; Box { IconButton(onClick = { menu = true }) { Icon(Icons.Default.MoreVert, "Actions") }; DropdownMenu(expanded = menu, onDismissRequest = { menu = false }) { DropdownMenuItem(text = { Text("Preview") }, onClick = { menu = false; nav.navigate("${Routes.FILE_VIEWER}/${record.id}") }); DropdownMenuItem(text = { Text("Upload now") }, onClick = { menu = false }); DropdownMenuItem(text = { Text("Download") }, onClick = { menu = false }); DropdownMenuItem(text = { Text("Share") }, onClick = { menu = false }); HorizontalDivider(); DropdownMenuItem(text = { Text("File details") }, onClick = { menu = false }) } } } } }
@Composable private fun Preview(record: FileRecord, tint: Color) { val context = LocalContext.current; val bitmap by produceState<Bitmap?>(null, record.uri) { value = withContext(Dispatchers.IO) { previewBitmap(context, record) } }; Box(Modifier.size(62.dp).clip(RoundedCornerShape(14.dp)).background(tint.copy(alpha = .09f)), contentAlignment = Alignment.Center) { if (bitmap != null) Image(bitmap!!.asImageBitmap(), null, Modifier.fillMaxSize(), contentScale = ContentScale.Crop) else Icon(when (record.category) { BackupCategory.PHOTOS -> Icons.Default.Image; BackupCategory.VIDEOS -> Icons.Default.VideoFile; BackupCategory.PDFS, BackupCategory.WORD_EXCEL -> Icons.Default.Description; BackupCategory.AUDIO, BackupCategory.CALL_RECORDINGS -> Icons.Default.AudioFile; BackupCategory.OTHER_FILES -> Icons.Default.InsertDriveFile }, null, tint = tint, modifier = Modifier.size(29.dp)); Icon(if (record.status == UploadStatus.UPLOADED) Icons.Default.CheckCircle else Icons.Default.Schedule, null, tint = if (record.status == UploadStatus.UPLOADED) Green else Orange, modifier = Modifier.align(Alignment.BottomEnd).padding(4.dp).size(18.dp)) } }

@OptIn(ExperimentalMaterial3Api::class)
@Composable private fun FilesFilterSheet(category: BackupCategory?, status: String, sort: String, onCategory: (BackupCategory?) -> Unit, onStatus: (String) -> Unit, onSort: (String) -> Unit, reset: () -> Unit, close: () -> Unit) { ModalBottomSheet(onDismissRequest = close, containerColor = Color.White) { Column(Modifier.padding(horizontal = 18.dp).padding(bottom = 18.dp)) { Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) { Column(Modifier.weight(1f)) { Text("Filters & Sort", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold); Text("Organise your AirDrive files", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant) }; IconButton(onClick = close) { Icon(Icons.Default.Close, "Close") } }; Text("File Type", fontWeight = FontWeight.Bold, modifier = Modifier.padding(vertical = 8.dp)); filters.chunked(3).forEach { row -> Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) { row.forEach { f -> Surface(modifier = Modifier.weight(1f).clickable { onCategory(f.category) }, shape = RoundedCornerShape(14.dp), color = if (category == f.category) PurpleSoft else Color(0xFFFBFCFF), border = if (category == f.category) BorderStroke(1.dp, Purple.copy(alpha = .55f)) else null) { Column(Modifier.padding(vertical = 11.dp).fillMaxWidth(), horizontalAlignment = Alignment.CenterHorizontally) { Icon(f.icon, null, tint = if (category == f.category) Purple else MaterialTheme.colorScheme.onSurfaceVariant); Text(f.label, style = MaterialTheme.typography.labelSmall) } } }; repeat(3 - row.size) { Spacer(Modifier.weight(1f)) } }; Spacer(Modifier.height(7.dp)) }; Text("Upload Status", fontWeight = FontWeight.Bold, modifier = Modifier.padding(vertical = 6.dp)); Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) { StatusFilter("All files", status.isEmpty(), Purple, Modifier.weight(1f)) { onStatus("") }; StatusFilter("Uploaded", status == "UPLOADED", Green, Modifier.weight(1f)) { onStatus("UPLOADED") }; StatusFilter("Pending", status == "PENDING", Orange, Modifier.weight(1f)) { onStatus("PENDING") } }; Text("Sort By", fontWeight = FontWeight.Bold, modifier = Modifier.padding(top = 13.dp, bottom = 4.dp)); listOf("newest" to "Newest first", "oldest" to "Oldest first", "largest" to "Largest size", "smallest" to "Smallest size", "name" to "Name (A–Z)", "name_desc" to "Name (Z–A)").forEach { (v, l) -> Row(Modifier.fillMaxWidth().clickable { onSort(v) }, verticalAlignment = Alignment.CenterVertically) { RadioButton(selected = sort == v, onClick = { onSort(v) }, colors = RadioButtonDefaults.colors(selectedColor = Purple)); Text(l) } }; Spacer(Modifier.height(8.dp)); OutlinedButton(onClick = {}, modifier = Modifier.fillMaxWidth(), shape = RoundedCornerShape(13.dp)) { Icon(Icons.Default.CalendarMonth, null); Spacer(Modifier.width(7.dp)); Text("Any time"); Spacer(Modifier.weight(1f)); Text("⌄") }; Spacer(Modifier.height(14.dp)); Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) { OutlinedButton(onClick = reset, modifier = Modifier.weight(1f), shape = RoundedCornerShape(14.dp)) { Text("Reset") }; Button(onClick = close, modifier = Modifier.weight(1f), shape = RoundedCornerShape(14.dp), colors = ButtonDefaults.buttonColors(containerColor = Purple)) { Text("Apply") } } } } }
@Composable private fun StatusFilter(label: String, selected: Boolean, accent: Color, modifier: Modifier, click: () -> Unit) { Surface(modifier = modifier.clickable(onClick = click), shape = RoundedCornerShape(13.dp), color = accent.copy(alpha = if (selected) .1f else .035f), border = if (selected) BorderStroke(1.dp, accent.copy(alpha = .5f)) else null) { Column(Modifier.padding(vertical = 10.dp).fillMaxWidth(), horizontalAlignment = Alignment.CenterHorizontally) { Icon(if (label == "Uploaded") Icons.Default.CheckCircle else if (label == "Pending") Icons.Default.Schedule else Icons.Default.GridView, null, tint = accent, modifier = Modifier.size(18.dp)); Text(label, style = MaterialTheme.typography.labelSmall) } } }
@Composable private fun EmptyFiles() { Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) { Text("No files found", color = MaterialTheme.colorScheme.onSurfaceVariant) } }
private fun sortText(s: String) = when (s) { "oldest" -> "Oldest first"; "largest" -> "Largest size"; "smallest" -> "Smallest size"; "name" -> "Name (A–Z)"; "name_desc" -> "Name (Z–A)"; else -> "Newest first" }
private fun categoryTint(c: BackupCategory) = when (c) { BackupCategory.PHOTOS -> Color(0xFF25B5A7); BackupCategory.VIDEOS -> Orange; BackupCategory.PDFS -> Color(0xFFE53935); BackupCategory.WORD_EXCEL -> Color(0xFF3478D4); BackupCategory.AUDIO -> Purple; BackupCategory.CALL_RECORDINGS -> Color(0xFFE85D75); BackupCategory.OTHER_FILES -> Color(0xFF60758F) }
private fun previewBitmap(context: android.content.Context, r: FileRecord): Bitmap? { val u = Uri.parse(r.uri); return runCatching { when { u.scheme.equals("file", true) -> { val p = u.path ?: return null; if (r.category == BackupCategory.PHOTOS) BitmapFactory.decodeFile(p) else if (r.category == BackupCategory.VIDEOS) MediaMetadataRetriever().let { x -> x.setDataSource(p); val b = x.getFrameAtTime(0); x.release(); b } else null }; u.scheme.equals("content", true) -> { if (r.category == BackupCategory.PHOTOS) context.contentResolver.openInputStream(u)?.use(BitmapFactory::decodeStream) else if (r.category == BackupCategory.VIDEOS) MediaMetadataRetriever().let { x -> x.setDataSource(context, u); val b = x.getFrameAtTime(0); x.release(); b } else null }; else -> null } }.getOrNull() }